  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C02", "C01", "C06", "C12", "C14", "C03", "C08", "C05", "C09", "C16", "C13"],
  "contradictory_card_ids": ["C50", "C54"],
  "prediction_basis_card_ids": ["C02", "C01", "C03", "C05", "C08", "C13", "C16"],
  "claims": [
    {
      "claim": "The closest structural context, a fused pyrazolopyrimidinone lactam with a pyridine sulfonamide-linked basic piperazine, showed 34% oral bioavailability derived from IV and oral profiles in fasted healthy volunteers, directly supporting F >= 20% for a sulfonamide-linked basic amine on a fused lactam.",
      "card_ids": ["C02"]
    },
    {
      "claim": "Ziprasidone, a fused lactam with a basic piperazine side chain, showed 30% fasted and about 60% fed absolute oral bioavailability, both above threshold.",
      "card_ids": ["C01", "C06", "C12", "C14"]
    },
    {
      "claim": "Praziquantel, an isoquinolinone-type lactam, retained 27.2% oral bioavailability even in cirrhotic patients, supporting positive oral exposure for isoquinolinone-related structures.",
      "card_ids": ["C03"]
    },
    {
      "claim": "Other training contexts are at or above threshold: niraparib about 73% fasted, didanosine 29% fasted, thalidomide 80 to 100%, and gaboxadol high in humans.",
      "card_ids": ["C08", "C05", "C09", "C16", "C13"]
    },
    {
      "claim": "L5 efflux records are mechanistic only. Vardenafil, a sulfonamide basic amine on a fused heterocycle, showed efflux ratio 7.27, and CPI-169 showed the highest efflux ratio among tested compounds, indicating efflux liability, but no F value is reported for either.",
      "card_ids": ["C50", "C54"]
    },
    {
      "claim": "Efflux substrate status alone does not imply low F. Lenalidomide, palbociclib, and ciprofloxacin are efflux substrates or show moderate permeability yet have adequate oral exposure in their own contexts.",
      "card_ids": ["C59", "C53", "C61", "C56", "C58"]
    },
    {
      "claim": "L5 permeability records are mixed. Compound 17b showed good A-B permeability with no efflux, while ciprofloxacin showed moderate jejunal Papp, so the family does not affirm presystemic loss for the query.",
      "card_ids": ["C51", "C55", "C56", "C58"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C50", "C51", "C52", "C53", "C54", "C55", "C56", "C57", "C58", "C59", "C60", "C61"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "No query-specific efflux, permeability, or intestinal metabolism assay is supplied.",
    "L5 records concern other molecules. Vardenafil is the closest chemotype with efflux liability, but no F value is reported.",
    "First-pass hepatic metabolism and formulation effects for the query are unmeasured.",
    "The query's low neutral fraction and logD -1.42 raise passive permeability uncertainty, but this is not affirmative evidence of F below 20%."
  ],
  "decision_summary": "Prediction remains high. L5 gut-wall efflux evidence is mechanistic and mixed. Related sulfonamide basic-amine molecules show efflux liability, but the same family includes efflux substrates with adequate oral exposure, and no direct low-F outcome for the query or a close analog is present. The closest direct context C02 reports 34% F, above threshold. Confidence stays moderate."
}

